import { SheetBody } from '../../slots/defs/sheetBody';
import { useClaims } from '../claims/claims';
import { gradeOn, liveHolds, usePeople } from '../people/people';
import { claimDue, heldParts, personDueTotal, rateOn, useRates } from '../rates/rates';
import { periodOf, usePeriods } from '../periods/periods';
import { useCap, useFloor, useLate } from '../access/access';
import { useSheetToday } from '../sheet/sheet';
import { getJson } from '../../api/http';
import type { Pool } from '../pools/pools';
import { downloadCsv } from './csv';
import { useCutTotals } from '../pools/pools';

// Downloads the people as a CSV file: a header line, then one line per person in list order,
// retired people included, with the grade in force today, the retired-from date ('' when not
// retired) and the due-total as the list shows it. Lines end with a line feed. While an as-of date
// is set every figure is as of it, as the list shows it then.
function ExportPeople({ sheetId }: { sheetId: string }) {
  const people = usePeople(sheetId).data ?? [];
  const claims = useClaims(sheetId).data ?? [];
  const rates = useRates(sheetId).data ?? [];
  const today = useSheetToday(sheetId);
  const floor = useFloor(sheetId);
  const late = useLate(sheetId);
  const cap = useCap(sheetId);
  const cutOf = useCutTotals(sheetId);

  const download = () => {
    const lines = [['name', 'grade', 'retired-from', 'due-total']];
    for (const p of people) {
      const own = claims.filter((c) => c.personId === p.id);
      lines.push([p.name, p.grade, p.retiredFrom, personDueTotal(rates, p.grades, today, own, liveHolds(p, today), floor, late, cap, heldParts(p.id, people, claims, rates, today, floor, late), cutOf(p.id))]);
    }
    downloadCsv(`people-${sheetId}.csv`, lines);
  };

  return (
    <p>
      <button type="button" data-testid="export-people" onClick={download}>
        Export people (CSV)
      </button>
    </p>
  );
}

// Downloads the claims as a CSV file: a header line, then one line per claim, people in list order
// (retired people included) and each person's claims oldest first, with the number, due and period
// as the claim's row shows them. Quoted and ended as the people export.
function ExportClaims({ sheetId }: { sheetId: string }) {
  const people = usePeople(sheetId).data ?? [];
  const claims = useClaims(sheetId).data ?? [];
  const rates = useRates(sheetId).data ?? [];
  const periods = usePeriods(sheetId).data ?? [];
  const floor = useFloor(sheetId);
  const late = useLate(sheetId);

  const download = () => {
    const lines = [['person', 'number', 'date', 'amount', 'due', 'status', 'period']];
    for (const p of people) {
      // The sheet's claims come newest first.
      const own = claims.filter((c) => c.personId === p.id).reverse();
      for (const c of own) {
        const grade = gradeOn(p.grades, c.date);
        const due = claimDue(c, rateOn(rates, grade, c.date, c.id), floor, late, grade);
        lines.push([p.name, c.number, c.date, c.amount, due, c.status, periodOf(periods, c.dueBy)?.name ?? '']);
      }
    }
    downloadCsv(`claims-${sheetId}.csv`, lines);
  };

  return (
    <p>
      <button type="button" data-testid="export-claims" onClick={download}>
        Export claims (CSV)
      </button>
    </p>
  );
}

// Downloads the pools as a CSV file: a header line, then one line per member, pools in the order
// added and each pool's members in the order added, a member pool as pool:<name> and the cut as
// the pool's row shows it ('' when none). Quoted and ended as the people export. The pools are read
// afresh when pressed, so a change just made is always in the file; while an as-of date is set they
// are read as of it (members, pot and cuts as they stood then).
function ExportPools({ sheetId }: { sheetId: string }) {
  const download = async () => {
    const { pools } = await getJson<{ pools: Pool[] }>(`/api/sheets/${encodeURIComponent(sheetId)}/pools`);
    const lines = [['pool', 'member', 'share', 'cut']];
    for (const p of [...pools].sort((a, b) => a.added - b.added)) {
      for (const m of p.members) {
        lines.push([p.name, m.memberPool ? `pool:${m.memberPool}` : m.name, m.share, m.cut]);
      }
    }
    downloadCsv(`pools-${sheetId}.csv`, lines);
  };

  return (
    <p>
      <button type="button" data-testid="export-pools" onClick={() => void download()}>
        Export pools (CSV)
      </button>
    </p>
  );
}

export const contributions = [
  SheetBody.fill({ order: 2, Component: ExportPeople }),
  SheetBody.fill({ order: 2.1, Component: ExportClaims }),
  SheetBody.fill({ order: 2.2, Component: ExportPools }),
];
// The app's fetch surface. A non-2xx REJECTS, so useQuery/useMutation surface the failure instead
// of a silent `if (res.ok)` that leaves the UI showing stale data.
// A non-2xx response, carrying its status so a caller can tell one refusal from another.
export class HttpError extends Error {
  constructor(message: string, readonly status: number) {
    super(message);
  }
}

// The as-of date the screen reads the sheet at ('' for now): the `asof` search param. While it is set
// every read names it, so the server answers with the sheet as it stood then, and every change is
// refused here, never sent — the form that made it shows its usual error. Loading a sheet is no
// change: it only re-reads one.
export const ASOF_PARAM = 'asof';

function asOf(): string {
  return new URLSearchParams(window.location.search).get(ASOF_PARAM) ?? '';
}

function refuseWhileAsOf(method: string, path: string): void {
  if (asOf() !== '' && !path.endsWith('/load')) {
    throw new HttpError(`${method} ${path} -> refused while viewing as of ${asOf()}`, 409);
  }
}

// The preview date the screen reads the sheet at ('' for none): the `preview` search param. While it
// is set (and no as-of date is) every read names it, so the server answers with the sheet's current
// records as if its today were that date; changes never carry it and use the sheet's real today.
export const PREVIEW_PARAM = 'preview';

export function previewDate(): string {
  if (asOf() !== '') return '';
  return new URLSearchParams(window.location.search).get(PREVIEW_PARAM) ?? '';
}

async function send<T>(path: string, init?: RequestInit): Promise<T> {
  const res = await fetch(path, init);
  if (!res.ok) {
    throw new HttpError(`${init?.method ?? 'GET'} ${path} -> ${res.status}`, res.status);
  }
  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
}

// A read that depends on who is signed in names them too.
export function getJson<T>(path: string, user?: string): Promise<T> {
  const headers: Record<string, string> = {};
  if (user !== undefined) headers['X-User'] = encodeURIComponent(user);
  const date = asOf();
  if (date !== '') headers['X-As-Of'] = date;
  const preview = previewDate();
  if (preview !== '') headers['X-Preview'] = preview;
  return send<T>(path, { headers });
}

// A read at the sheet's real today, whatever preview date the screen shows (an as-of date still applies).
export function getJsonUnpreviewed<T>(path: string): Promise<T> {
  const date = asOf();
  return send<T>(path, date !== '' ? { headers: { 'X-As-Of': date } } : undefined);
}

// A read of the sheet as it is now, whatever as-of date the screen shows.
export function getJsonNow<T>(path: string): Promise<T> {
  return send<T>(path);
}

// A change is made by the signed-in user: name them, and the server records who made it.
function jsonHeaders(user?: string): HeadersInit {
  return user === undefined
    ? { 'Content-Type': 'application/json' }
    : { 'Content-Type': 'application/json', 'X-User': encodeURIComponent(user) };
}

export async function postJson<T>(path: string, body: unknown, user?: string): Promise<T> {
  refuseWhileAsOf('POST', path);
  return send<T>(path, {
    method: 'POST',
    headers: jsonHeaders(user),
    body: JSON.stringify(body),
  });
}
package net.officefloor.hq.app.sheet;

import jakarta.servlet.http.HttpServletRequest;
import java.time.LocalDate;
import net.officefloor.hq.app.AsOf;
import net.officefloor.hq.app.Preview;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

/**
 * Loads the sheet. A read made as of a date (see {@link AsOf}) loads it as it stood at the end of
 * that date, the date standing in for its today; a read made at a preview date (see {@link Preview})
 * loads it as it is now, the preview date standing in for its today. A change always loads it as it
 * is now, at its real today.
 */
public class LoadSheet {
    public void load(@PathVariable("sheetId") String sheetId, SheetRepository repository,
            HttpServletRequest request, Out<Sheet> sheetOut) throws SheetNotFoundException {
        Sheet sheet = repository.find(sheetId == null ? "" : sheetId.trim());
        if (sheet == null) throw new SheetNotFoundException(sheetId);
        boolean read = "GET".equals(request.getMethod());
        LocalDate asOf = read ? AsOf.of(request) : null;
        LocalDate preview = read && asOf == null ? Preview.of(request) : null;
        if (asOf != null) sheetOut.set(repository.asOf(sheet, asOf));
        else if (preview != null) sheetOut.set(new Sheet(sheet.id(), preview, sheet.archived()));
        else sheetOut.set(sheet);
    }
}

